import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';

const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
if (process.env.DISPLAY) {} else {
  try { process.env.DISPLAY = `:${readFileSync(join(runtime, 'display'), 'utf8').trim()}`; } catch {}
}
if (process.env.CHROME_PATH) launchOptions.executablePath = process.env.CHROME_PATH;
else launchOptions.executablePath = '/opt/google/chrome/chrome';

const url = process.env.URL || 'http://localhost:3000';
const out = process.env.OUT || '/tmp/opencode/shot.jpg';
const width = Number(process.env.W || 1280);
const height = Number(process.env.H || 800);
const js = process.env.JS || '';

const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
const errs = [];
page.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__apex && document.querySelector('#screen-menu.is-active') && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 45000 });
await page.evaluate(async () => { await document.fonts?.ready; await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))); });
if (js) {
  await page.evaluate(js);
  await page.waitForTimeout(Number(process.env.WAIT || 800));
}
if (process.env.CLICK) {
  const sel = process.env.CLICK;
  await page.click(sel);
  await page.waitForTimeout(Number(process.env.WAIT || 800));
}
await page.screenshot({ path: out, type: out.endsWith('.jpg') ? 'jpeg' : 'png', quality: out.endsWith('.jpg') ? 80 : undefined, timeout: 30000 });
console.log('saved', out);
if (errs.length) console.log('ERRORS:\n' + errs.join('\n'));
await browser.close();

