.garage-stage { position: relative; min-height: 0; z-index: 2; pointer-events: none; }
.garage-stage-copy { position: absolute; left: 0; top: 4vh; max-width: 330px; }
.garage-stage-copy .eyebrow { font-size: 8px; }
.garage-stage-copy h2 {
  margin: 16px 0 12px; font-family: var(--font-display); font-weight: 700;
  font-size: clamp(42px, 5.2vw, 68px); line-height: .84; letter-spacing: -.01em; text-transform: uppercase;
  text-shadow: 0 3px 30px rgba(0,0,0,.55);
}
.garage-stage-copy h2 em { font-style: normal; color: transparent; -webkit-text-stroke: 1px rgba(243,239,229,.78); }
.garage-stage-copy p { max-width: 300px; margin: 0; color: #a8abb1; font-size: 12px; font-weight: 300; line-height: 1.6; }
.garage-live {
  position: absolute; right: 0; top: 4vh;
  display: flex; align-items: center; gap: 12px;
  border: 1px solid rgba(255,255,255,.12); background: rgba(9,11,15,.62);
  backdrop-filter: blur(14px); padding: 10px 14px;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
}
.garage-live-dot {
  width: 26px; height: 26px; border-radius: 50%; background: var(--orange);
  border: 1px solid rgba(255,255,255,.4); transition: background .25s, box-shadow .25s;
}
.garage-live .mono { display: block; color: var(--dim-2); font-size: 7px; margin-bottom: 1px; }
.garage-live strong { font-family: var(--font-display); font-size: 19px; font-weight: 600; letter-spacing: .1em; color: var(--cream); }
.garage-live-name { color: var(--orange) !important; font-size: 7.5px !important; margin-left: 4px; align-self: flex-end; padding-bottom: 3px; }

.garage-dock {
  position: relative; z-index: 5; width: 100%; padding: 15px 22px 11px;
}
.garage-dock-head { display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line-soft); padding-bottom: 10px; }
.garage-dock-head .mono { color: var(--dim); font-size: 8px; }
.garage-dock-body {
  display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(0, 1fr);
  gap: 32px; align-items: start; padding: 14px 0 12px;
}
.garage-presets > .mono, .garage-custom > .mono { display: block; color: var(--dim-2); font-size: 7.5px; margin-bottom: 10px; letter-spacing: .18em; }
.garage-swatches { display: grid; grid-template-columns: repeat(14, minmax(0, 1fr)); gap: 7px; }
.garage-swatch {
  position: relative; aspect-ratio: 1; border-radius: 50%; background: var(--swatch);
  border: 1px solid rgba(255,255,255,.18); cursor: pointer;
  transition: transform .2s var(--ease), box-shadow .2s, border-color .2s;
}
.garage-swatch span { position: absolute; inset: 3px; border-radius: 50%; border: 1px solid transparent; transition: border-color .2s; }
.garage-swatch:hover { transform: translateY(-3px); border-color: rgba(255,255,255,.6); }
.garage-swatch.is-active { border-color: var(--cream); box-shadow: 0 0 0 2px rgba(243,239,229,.2), 0 0 22px var(--swatch); transform: translateY(-2px); }
.garage-swatch.is-active span { border-color: rgba(0,0,0,.28); }
.garage-custom-row { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }
.garage-wheel { position: relative; display: inline-flex; cursor: pointer; flex: none; }
.garage-wheel input { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; }
.garage-wheel-ui {
  display: inline-flex; align-items: center; gap: 9px; padding: 9px 12px;
  border: 1px solid var(--line); background: rgba(255,255,255,.025);
  font-family: var(--font-display); font-weight: 600; font-size: 10px; letter-spacing: .1em; color: var(--cream);
  transition: border-color .2s, background .2s;
}
.garage-wheel:hover .garage-wheel-ui { border-color: rgba(255,255,255,.38); background: rgba(255,255,255,.05); }
.garage-wheel-ui i {
  width: 17px; height: 17px; border-radius: 50%; display: block;
  background: conic-gradient(#ff4d1f, #ffcf5c, #b9f34a, #17c9a4, #25b8d8, #9b6cff, #e83e8c, #ff4d1f);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.45);
}
.garage-hex {
  display: flex; align-items: center; gap: 5px; padding: 2px 3px 2px 9px;
  border: 1px solid var(--line); background: rgba(5,7,10,.72); transition: border-color .2s;
}
.garage-hex:focus-within { border-color: rgba(255,255,255,.32); }
.garage-hex label { color: var(--dim-2); font-size: 7px; }
.garage-hash { color: var(--orange); font-family: var(--font-mono); font-size: 11px; }
.garage-hex input {
  width: 78px; padding: 7px 0; border: 0; background: none; outline: none;
  color: var(--cream); font: 600 12px var(--font-mono); letter-spacing: .12em; text-transform: uppercase;
}
.garage-hex input::placeholder { color: var(--dim-2); }
.garage-hex input.is-invalid { color: var(--bad); }
.garage-hex .btn-sm { padding: 6px 10px; min-width: 0; min-height: 28px; font-size: 9px; }
.garage-reset { margin-left: auto; white-space: nowrap; }
.garage-dock-foot {
  display: flex; justify-content: space-between; gap: 14px;
  border-top: 1px solid var(--line-soft); padding-top: 9px;
  color: var(--dim-2); font-size: 7px; letter-spacing: .14em;
}

.menu-bottom { position: relative; z-index: 2; border-top: 1px solid var(--line-soft); padding-top: 14px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }

