1092:   const first = history[0];
1093:   const last = history[history.length - 1];
1094:   if (progress >= last.p) return 0;
1095:   if (progress < first.p) {
1096:     // Before the leader's first sample (the grid): no elapsed race time yet.
1097:     if (race.time < 600) return 0;
1098:     const metres = (first.p - progress) * race.track.length;
1099:     return metres / Math.max(24, speed);
1100:   }
1101:   // Binary search for the first timeline sample at or beyond this progress.
1102:   let lo = 0, hi = history.length - 1;
1103:   while (lo < hi) {
1104:     const mid = (lo + hi) >> 1;
1105:     if (history[mid].p >= progress) hi = mid; else lo = mid + 1;
1106:   }
1107:   const b = history[lo];
1108:   const a = history[Math.max(0, lo - 1)];
1109:   if (b === a) return Math.max(0, (race.time - b.t) / 1000);
1110:   const f = clamp((progress - a.p) / Math.max(1e-6, b.p - a.p), 0, 1);
1111:   const tAt = a.t + (b.t - a.t) * f;
1112:   return Math.max(0, (race.time - tAt) / 1000);
