import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, resolve } from 'node:path';

const root = process.cwd();
const port = Number(process.env.PORT || 3000);

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.wasm': 'application/wasm',
  '.glb': 'model/gltf-binary',
  '.txt': 'text/plain; charset=utf-8'
};

const server = createServer(async (req, res) => {
  try {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.writeHead(405, { Allow: 'GET, HEAD' });
      res.end();
      return;
    }

    const url = new URL(req.url || '/', 'http://localhost');
    let filePath = resolve(root, `.${decodeURIComponent(url.pathname)}`);
    if (filePath !== root && !filePath.startsWith(root + '/')) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    let info = await stat(filePath);
    if (info.isDirectory()) {
      filePath = join(filePath, 'index.html');
      info = await stat(filePath);
    }

    const body = await readFile(filePath);
    res.writeHead(200, {
      'Content-Type': MIME[extname(filePath).toLowerCase()] || 'application/octet-stream',
      'Content-Length': body.length,
      'Cache-Control': 'no-cache, no-store, must-revalidate',
      'X-Content-Type-Options': 'nosniff'
    });
    res.end(req.method === 'HEAD' ? undefined : body);
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not found');
  }
});

server.listen(port, '0.0.0.0', () => {
  console.log(`APEX INK ready on http://localhost:${port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => process.exit(0)));
}

## Process lifecycle

- Run long-lived servers and watchers in a persistent session such as tmux.
- Do not background them in bounded commands without explicit detachment and cleanup.
- After a timeout, inspect the process and endpoint before retrying or claiming failure.

## Linux browser and WebGPU capture

- Use the preinstalled `playwright-cli` executable from Actions or SSH.
- Use its headed Chromium, persistent Xvfb display, and SwiftShader configuration.
- Run `playwright-cli open http://localhost:3002` for the Pascal development server.
- Load a saved scene. Wait for actual geometry and the active WebGPU renderer.
- Run `playwright-cli screenshot --filename=screenshots/linux.png` after creating the output directory.
- Inspect the image. Reject loading screens, empty grids, and blank canvases.
- Report SwiftShader as CPU software rendering. Do not claim GPU hardware acceleration.
- Inspect `$HOME/.local/share/omgithub-playwright/linux.json` for launch settings.
- Use `playwright-cli --help` for commands and named sessions. Pass configuration only to `open`.
name: OpenCode
run-name: "OpenCode #${{ github.event.issue.number || inputs.issue_number }}"
on:
  issues:
    types:
      - opened
  workflow_dispatch:
    inputs:
      issue_number:
        required: true
        type: string
        description: Existing issue to run
permissions: {}
concurrency:
  group: opencode-issue-${{ github.repository }}-${{ github.event.issue.number || inputs.issue_number }}
  cancel-in-progress: false
jobs:
  prepare:
    runs-on: ubuntu-latest
    permissions:
      id-token: write
      contents: write
      issues: write
      actions: write
    outputs:
      approved: ${{ steps.prepare.outputs.approved }}
      issue_number: ${{ steps.prepare.outputs.issue_number }}
      request: ${{ steps.prepare.outputs.request }}
      issue_title: ${{ steps.prepare.outputs.issue_title }}
      labels_json: ${{ steps.prepare.outputs.labels_json }}
      sender: ${{ steps.prepare.outputs.sender }}
      target_ref: ${{ steps.prepare.outputs.target_ref }}
      target_sha: ${{ steps.prepare.outputs.target_sha }}
    steps:
      - name: Authenticate status callbacks
        continue-on-error: true
        shell: bash
        env:
          ISSUE_NUMBER: ${{ github.event.issue.number || github.event.needs.prepare.outputs.issue_number }}
          OMGITHUB_ORIGIN: ${{ vars.OMGITHUB_ORIGIN || 'https://omgithub.com' }}
        run: |
          /usr/bin/time -p node --input-type=module <<'NODE'
          import { appendFileSync } from 'node:fs';
          const env = process.env;
          const origin = env.OMGITHUB_ORIGIN.replace(/\/$/, '');
          const url = new URL(env.ACTIONS_ID_TOKEN_REQUEST_URL);
          url.searchParams.set('audience', origin);
          async function json(url, options) {
            const response = await fetch(url, { ...options, signal: AbortSignal.timeout(15000) });
            if (!response.ok) throw new Error(`Callback authentication HTTP ${response.status}`);
            return response.json();
          }
          for (let attempt = 0; attempt < 8; attempt++) {
            try {
              const identity = await json(url, { headers: { authorization: `Bearer ${env.ACTIONS_ID_TOKEN_REQUEST_TOKEN}` } });
              const { token } = await json(`${origin}/api/github/${env.GITHUB_REPOSITORY}/issues/${env.ISSUE_NUMBER}/callback-token`, {
                method: 'POST', headers: { authorization: `Bearer ${identity.value}`, 'content-type': 'application/json' },
                body: JSON.stringify({ run: env.GITHUB_RUN_ID, attempt: Number(env.GITHUB_RUN_ATTEMPT) })
              });
              console.log(`::add-mask::${token}`);
              appendFileSync(env.GITHUB_ENV, `OMGITHUB_CALLBACK_TOKEN=${token}\n`);
              break;
            } catch (error) {
              if (attempt === 7) throw error;
              await new Promise(resolve => setTimeout(resolve, Math.min(20000, 3000 * 2 ** attempt)));
            }
          }
          NODE
      - name: Register preparation
        continue-on-error: true
        env:
          GH_TOKEN: ${{ github.token }}
          ISSUE_NUMBER: ${{ github.event.issue.number || github.event.needs.prepare.outputs.issue_number }}
          OMGITHUB_ORIGIN: ${{ vars.OMGITHUB_ORIGIN || 'https://omgithub.com' }}
        run: |
          /usr/bin/time -p curl --fail-with-body --silent --show-error --retry 2 --retry-all-errors --max-time 15 \
            -H "Authorization: Bearer $OMGITHUB_CALLBACK_TOKEN" -H 'Content-Type: application/json' \
            --data "{\"run\":\"$GITHUB_RUN_ID\",\"attempt\":$GITHUB_RUN_ATTEMPT,\"sequence\":1,\"state\":\"starting\",\"phase\":\"initializing\"}" \
            "$OMGITHUB_ORIGIN/api/github/$GITHUB_REPOSITORY/issues/$ISSUE_NUMBER/run"
      - name: Checkout trusted preparation code
        uses: actions/checkout@v6
        with:
          persist-credentials: false
      - name: Validate and claim issue request
        id: prepare
        env:
          OPENCODE_ACCESS: ${{ vars.OPENCODE_ACCESS || 'writers' }}
          GH_TOKEN: ${{ github.token }}
        run: /usr/bin/time -p node .omgithub/scripts/opencode-prepare.mjs
      - name: Report branch handoff
        if: steps.prepare.outputs.redispatched == 'true'
        continue-on-error: true
        env:
          GH_TOKEN: ${{ github.token }}
          ISSUE_NUMBER: ${{ github.event.issue.number || github.event.needs.prepare.outputs.issue_number }}
          OMGITHUB_ORIGIN: ${{ vars.OMGITHUB_ORIGIN || 'https://omgithub.com' }}
        run: |
          sequence=$(/usr/bin/time -p node -p 'Date.now()')
          /usr/bin/time -p curl --fail-with-body --silent --show-error --retry 2 --retry-all-errors --max-time 15 \
            -H "Authorization: Bearer $OMGITHUB_CALLBACK_TOKEN" -H 'Content-Type: application/json' \
            --data "{\"run\":\"$GITHUB_RUN_ID\",\"attempt\":$GITHUB_RUN_ATTEMPT,\"sequence\":$sequence,\"state\":\"starting\",\"phase\":\"queued\"}" \
            "$OMGITHUB_ORIGIN/api/github/$GITHUB_REPOSITORY/issues/$ISSUE_NUMBER/run"
