function updateAI(dt) {
  const tr = race.track;
  const L = tr.length;
  const diff = DIFFICULTY[diffLevel] || DIFFICULTY.pro;
  const ai = race.ai;
  const laneOffset = (a) => AI_LANES[a.lane] + Math.sin(a.dist/43 + a.phase)*0.16;

  // 1. Determine blockers and lane decisions using state before movement
  for (const a of ai) {
    a.laneCooldown = Math.max(0, a.laneCooldown - dt);
    let blocker = null;
    let blockerGap = Infinity;
    for (const b of ai) {
      if (b === a) continue;
      const gap = b.dist - a.dist;
      if (gap <= 0 || gap > 38) continue;
      // same lane if b lane equals or lateral close
      if (Math.abs(laneOffset(b) - laneOffset(a)) > 2.2) continue;
      if (gap < blockerGap) { blockerGap = gap; blocker = b; }
    }
    // also consider player? optional
    a.blocker = blocker; a.blockerGap = blockerGap;

    // lane change decision if blocked close and cooldown expired
    if (blocker && blockerGap < 22 && a.laneCooldown <= 0 && !a.finished) {
      const options = [];
      for (const dir of [-1, 1]) {
        const lane = a.lane + dir;
        if (lane < 0 || lane >= AI_LANES.length) continue;
        // check clear in that lane for ±10m
        let clear = true;
        for (const b of ai) {
          if (b === a || Math.abs(b.lane - lane) > 0) continue; // lane index
          const gap = b.dist - a.dist;
          if (gap > -8 && gap < 12) { clear = false; break; }
        }
        if (clear) options.push(lane);
      }
      if (options.length) {
        // choose the lane on the side with more room / prefer inside? Random slight
        a.lane = options[Math.random() < 0.5 ? 0 : options.length - 1];
        a.laneCooldown = 1.6 + Math.random()*1.4;
      }
    }
  }

  // 2. Move each AI
  for (const a of ai) {
    const norm = ((a.dist % L) + L) % L;
    const idx = ...
    const s = tr.samples[idx];
    const paceForm = 1 + Math.sin((race.time/1000) * a.formFreq + a.formPhase) * 0.008;
    // Launch delay
    const launch = race.time < a.startDelay * 1000 ? 0.35 : 1;
    let target = tr.speedProfile[idx] * diff.factor * a.pace * paceForm * launch;
    // corner skill? maybe per-driver
    // Traffic: if blocker in same lane...
    const blocker = a.blocker;
    if (blocker) {
      const gap = blocker.dist - a.dist;
      // if still same lane after decisions
      if (Math.abs(laneOffset(blocker) - laneOffset(a)) < 2.35) {
        const safe = 7 + a.speed * 0.12; // 10-18m
        if (gap < safe) {
          const follow = blocker.speed * (0.9 + clamp((gap - 2.5) / safe, 0, 0.1));
          target = Math.min(target, Math.max(8, follow));
        } else if (gap < 18) {
          target = Math.min(target, blocker.speed + (gap - 8) * 0.3);
        }
      }
    }
    // brake / accelerate
    if (a.speed < target) a.speed = Math.min(target, a.speed + diff.accel * dt);
    else a.speed = Math.max(target, a.speed - 28 * dt);
    a.dist += a.speed * dt;
    // clamp speed? target from profile.

